def transform (grid :list [list [int ]])->list [list [int ]]:
    if not grid or not grid [0 ]:
        return grid 

    H =len (grid )
    W =len (grid [0 ])

    # Create a copy to avoid mutating the original input
    new_grid =[row [:]for row in grid ]

    # Find the vertical extent of all non-zero pixels
    min_r =H 
    max_r =-1 
    for r in range (H ):
        for c in range (W ):
            if grid [r ][c ]!=0 :
                if r <min_r :
                    min_r =r 
                if r >max_r :
                    max_r =r 

                    # If the grid is empty, return it
    if max_r ==-1 :
        return new_grid 

        # The transformation is a vertical reflection (top-to-bottom symmetry)
        # We iterate through the rows and try to mirror them from the bottom part of the shape
    for r in range (min_r ,max_r +1 ):
    # Calculate the reflected row index within the bounding box of the shape
    # The center of the shape is (min_r + max_r) / 2
    # The reflection of r is: min_r + max_r - r
        r_ref =min_r +max_r -r 

        # We only care about mirroring if the reflected row is within the shape bounds
        if min_r <=r_ref <=max_r :
        # Check each column
            for c in range (W ):
            # If the current pixel is 0 but the reflected pixel is non-zero,
            # and the reflected pixel is part of a pattern, fill it.
            # We use the color of the reflected pixel.
                if grid [r ][c ]==0 and grid [r_ref ][c ]!=0 :
                # Check if this is a valid "completion". 
                # In Demo 1, row 2 is filled by row 8.
                # In Demo 2, row 5 is filled by row 0.
                    new_grid [r ][c ]=grid [r_ref ][c ]

                    # Second pass: sometimes the reflection itself needs to be applied to the other side
                    # (i.e., if we filled row 2 from row 8, we might need to ensure row 8 is consistent, 
                    # though in these demos the source is already complete).
                    # Let's refine: the rule is likely "make the shape vertically symmetric".

                    # Re-run the logic to ensure symmetry is fully applied
    for r in range (min_r ,max_r +1 ):
        r_ref =min_r +max_r -r 
        if min_r <=r_ref <=max_r :
            for c in range (W ):
                if new_grid [r ][c ]==0 and new_grid [r_ref ][c ]!=0 :
                    new_grid [r ][c ]=new_grid [r_ref ][c ]
                elif new_grid [r_ref ][c ]==0 and new_grid [r ][c ]!=0 :
                # This handles cases where the bottom is the template
                    pass 

    return new_grid

import numpy as np 

def transform (grid :list [list [int ]])->list [list [int ]]:
    grid_np =np .array (grid )
    rows ,cols =grid_np .shape 

    # Find the color of the object (assuming only one non-zero color exists)
    unique_colors =np .unique (grid_np )
    object_color =None 
    for color in unique_colors :
        if color !=0 :
            object_color =color 
            break 

    if object_color is None :
        return grid 

        # Create a mask of the background
    background_mask =(grid_np ==0 )

    # We want to find all 0-pixels that cannot reach the boundary.
    # We can do this by performing a flood fill from all boundary 0-pixels.
    # Any 0-pixel not reached by this flood fill is an internal cavity.

    reachable_from_boundary =np .zeros_like (background_mask ,dtype =bool )

    # Stack of pixels to visit for flood fill
    stack =[]

    # Initialize stack with all 0-pixels on the boundary
    for r in range (rows ):
        if grid_np [r ,0 ]==0 :
            stack .append ((r ,0 ))
            reachable_from_boundary [r ,0 ]=True 
        if grid_np [r ,cols -1 ]==0 :
            stack .append ((r ,cols -1 ))
            reachable_from_boundary [r ,cols -1 ]=True 

    for c in range (cols ):
        if grid_np [0 ,c ]==0 :
            if not reachable_from_boundary [0 ,c ]:
                stack .append ((0 ,c ))
                reachable_from_boundary [0 ,c ]=True 
        if grid_np [rows -1 ,c ]==0 :
            if not reachable_from_boundary [rows -1 ,c ]:
                stack .append ((rows -1 ,c ))
                reachable_from_boundary [rows -1 ,c ]=True 

                # Standard BFS/DFS to find all reachable 0-pixels
    while stack :
        curr_r ,curr_c =stack .pop ()

        # Check 4-neighbors
        for dr ,dc in [(-1 ,0 ),(1 ,0 ),(0 ,-1 ),(0 ,1 )]:
            nr ,nc =curr_r +dr ,curr_c +dc 
            if 0 <=nr <rows and 0 <=nc <cols :
                if grid_np [nr ,nc ]==0 and not reachable_from_boundary [nr ,nc ]:
                    reachable_from_boundary [nr ,nc ]=True 
                    stack .append ((nr ,nc ))

                    # The cavities are the 0-pixels that are NOT reachable from the boundary
    output_grid =grid_np .copy ()
    cavity_mask =background_mask &(~reachable_from_boundary )
    output_grid [cavity_mask ]=object_color 

    return output_grid .tolist ()
